import ch.jalu.configme.configurationdata.CommentsConfiguration;
import ch.jalu.configme.configurationdata CommentsConfigurationBuilder;
import ch.jalu.configme.settings.SettingsHolder;
import org.jetbrains.annotations.NotNull;
import org.junit.jupiter.api.Test;

public class CommentsConfigurationTests {

    @Test
    public void testConstructorWithoutComments() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        assert !configuration.comments.isEmpty();
    }

    @Test
    public void testConstructorWithNoComments() {
        CommentsConfigurationBuilder builder = new CommentsConfigurationBuilder();
        String comments = builder.build().toString();
        assert !comments.isEmpty();
        assert (!comments.contains("\n"));
    }

    @Test
    public void testSetCommentLinesSingleLine() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        configuration.setComment("path", "\n comment line 1\n");
        List<String> lines = configuration.getAllComments().values().stream()
                .map(List::size).toArray(Integer[]::new);
        assert (lines.length == 2 && lines[0] == "comment line 1" && lines[1] == "");
    }

    @Test
    public void testSetCommentLinesMultipleLines() {
        CommentsConfigurationBuilder builder = new CommentsConfigurationBuilder();
        String comments = builder.build().toString();
        List<String> lines = comments.split("\n");
        assert (lines.length > 0);
        for (String line : lines) {
            assert !line.isEmpty();
        }
    }

    @Test
    public void testGetAllCommentsNoComments() {
        CommentsConfiguration configuration = new CommentsConfiguration();
        Map<String, List<String>> commentsMap = configuration.getAllComments().toMap();
        assert commentsMap.isEmpty();
    }

    @Test
    public void testGetAllComments() {
        CommentsConfigurationBuilder builder = new CommentsConfigurationBuilder();
        String comments = builder.build().toString();
        Map<String, List<String>> commentsMap = comments.split("\n");
        assert !commentsMap.isEmpty();
    }
}
